def gcd(a, b):
    while b:
        a, b = b, a % b
    return a

# Contains the solution function for the Kitayuta's Garden problem

def solution(input_str):
    lines = input_str.strip().split('\n')
    n, m, k, p = map(int, lines[0].split())
    bamboos = []
    for i in range(1, n + 1):
        h, a = map(int, lines[i].split())
        bamboos.append((h, a))

    upper_bound = max(h + a * m for h, a in bamboos)

    def check(target):
        total_hits_needed = 0
        for h, a in bamboos:
            if h + a * m > target:
                needed = h + a * m - target
                hits_needed = (needed + p - 1) // p
                total_hits_needed += hits_needed
        return total_hits_needed <= k * m

    lo, hi = 0, upper_bound
    ans = upper_bound

    while lo <= hi:
        mid = (lo + hi) // 2
        if check(mid):
            ans = mid
            hi = mid - 1
        else:
            lo = mid + 1

    return str(ans)

