    max_team = 0
    for t in trainers:
        for team in t['wish_list']:
            max_team = max(max_team, team)
    T = max_team

    # For hate pairs, check quickly
    def has_hate(a, b):
        if a > b:
            a, b = b, a
        return (a, b) in hate

    # We'll use a greedy approach with local search
    # First, assign each trainer to a team from their wish list
    team_assignment = {}  # trainer_id -> team

