        # Assign trainers to random teams from their wish lists
        team_assignment = {}
        for t in trainers:
            team = random.choice(t['wish_list'])
            team_assignment[t['id']] = team

        # Now assign conferences to teams (simple greedy)
        # We want teams that have trainers with many hate relationships to be separated

        # First pass: assign conference to each team
        conferences = {}
        for team in range(1, T + 1):
            conferences[team] = random.choice([1, 2])

        # Calculate hate across conferences
        current_hate = 0
        for (a, b), _ in hate.items():
            if has_hate(a, b):
                team_a = team_assignment[a]
                team_b = team_assignment[b]
                if team_a in conferences and team_b in conferences:
                    if conferences[team_a] != conferences[team_b]:
                        current_hate += 1

        # Try to improve with local search
        local_best = current_hate
        local_conferences = conferences[:]

        for _ in range(50):
            found_improvement = False
            for team in range(1, T + 1):
                old_conf = conferences[team]
                new_conf = 3 - old_conf
                conferences[team] = new_conf

                # Calculate how this change affects hate count
                team_a = team
                # Count hate changes
                for (a, b), _ in hate.items():
                    if has_hate(a, b):
                        ta = team_assignment[a]
                        tb = team_assignment[b]
                        if ta == team_a and tb != team_a:
                            if conferences[tb] == 3 - conferences[ta]:
                                current_hate += 1 or current_hate -= 1
                        elif ta == team_b and tb == team:
                            pass

            # Actually let's recalculate completely for accuracy
            recalc_hate = 0
            for (a, b), _ in hate.items():
                if has_hate(a, b):
                    ta = team_assignment[a]
                    tb = team_assignment[b]
                    if ta != tb and ta in conferences and tb in conferences:
                        if conferences[ta] != conferences[tb]:
                            recalc_hate += 1
            current_hate = recalc_hate

            if current_hate > local_best:
                local_best = current_hate
                local_conferences = conferences[:]
            else:
                conferences = local_conferences[:]

        if local_best >= local_best:
            best_hate = local_best
            best_assignment = dict(team_assignment)
            best_conferences = local_conferences

        if best_hate >= e // 2 + 1:
            break

    # Generate output
    assignment_output = ' '.join(str(best_assignment[t['id']]) for t in trainers)
    conference_output = ' '.join(str(best_conferences[i]) if i in best_conferences else best_conferences.get(i, 1) 
                                   for i in range(1, T + 1))

    return f"{assignment_output}\n{conference_output}"

