    n, m = map(int, lines[0].split())

    ops = []
    for i in range(1, n + 1):
        parts = lines[i].split()
        t = int(parts[0])
        x_prime = int(parts[1])
        y = int(parts[2])
        x = x_prime / 100000.0
        ops.append((t, x, y))

    # visited[v] stores the earliest time step when value v was reached
    visited = [-1] * (m + 1)
    visited[0] = 0  # 0 bananas initially at time 0

    # result[j] stores earliest time to reach exactly j bananas (1-indexed, ignore index 0)
    result = [-1] * (m + 1)

    for time_step in range(1, n + 1):
        t, x, y = ops[time_step - 1]

        # Track values that could be reached at previous time step
        # We need to track which values were reachable at time_step-1 or earlier
        prev_reachable = set()
        for v in range(m + 1):
            if visited[v] <= time_step - 1:
                prev_reachable.add(v)

        # Generate new values at this time step
        new_reachable = set()

        for prev_val in prev_reachable:
            curr = prev_val

            # Apply 0 operations - value remains same
            if curr <= m:
                new_reachable.add(curr)

            # Apply operations 1 to y times
            for a in range(1, y + 1):
                if curr > m:
                    break

                if t == 1:
                    curr = int(math.ceil(curr + x))
                else:
                    curr = int(math.ceil(curr * x))

                if curr <= m:
                    new_reachable.add(curr)
                else:
                    break

        # Update visited tracking
        for val in new_reachable:
            if visited[val] == -1 or visited[val] >= time_step:
                visited[val] = time_step
                result[val] = time_step

                # Optimization: remove from prev_reachable to avoid re-processing
                if val not in prev_reachable:
                    pass

    # Build output
    output = []
    for j in range(1, m + 1):
        if visited[j] >= 1:
            output.append(str(visited[j]))
        else:
            output.append(str(-1))

    return ' '.join(output) + ' \n'

