                new_sums[new_sum] = min_components[s] + 1
            elif new_sums.get(new_sum, float('inf')) > min_components[s] + 1:
                new_sums[new_sum] = min_components[s] + 1

        # Update min_components with new sums
        for new_s, new_cnt in new_sums.items():
            if new_s not in min_components or new_cnt < min_components[new_s]:
                min_components[new_s] = new_cnt

    # Find the minimum roads needed (number of components - 1)
    min_roads = float('inf')

