    m = len(friends)

    if m == 0:
        return 0

    fri_map = {f: i for i, f in enumerate(friends)}

    friend_seg = [set() for _ in range(m)]
    for i, seg in enumerate(segments):
        for friend in seg:
            if friend in fri_map:
                friend_seg[fri_map[friend]].add(i)

    adj = [[False] * m for _ in range(m)]
    for i in range(m):
        for j in range(i + 1, m):
            if friend_seg[i] & friend_seg[j]:
                adj[i][j] = adj[j][i] = True

    # Maximum Independent Set using branch and bound
    best = [0]

    def solve(mask, count, k):
        if count + len(friends) - k <= best[0]:
            return

        if mask == (1 << m) - 1:
            best[0] = max(best[0], count)
            return

        # Find first unselected vertex
        first = k
        while first < m and ((mask >> first) & 1):
            first += 1

        if first >= m:
            best[0] = max(best[0], count)
            return

        # Branch: include vertex 'first'
        new_mask = mask | (1 << first)
        new_count = count + 1

        # Pruning: count conflicts with 'first'
        conflict_neighbors = 0
        for v in range(first + 1, m):
            if not ((mask >> v) & 1) and adj[first][v]:
                conflict_neighbors += 1

        # Only continue if there's potential to improve
        if best[0] < new_count + (len(friends) - first - conflict_neighbors):
            solve(new_mask, new_count, conflict_neighbors)

        # Branch: exclude vertex 'first'
        solve(mask, count, first + 1)

    solve(0, 0, 0)
    return str(best[0])

