        # All vertices in component must have same value
        return 2

    def count_C(comp):
        """|C| for a component: no edge has sum 2 (i.e., not both endpoints = 1)"""
        from itertools import product
        k = len(comp)
        count = 0
        for assignment in product([0, 1], repeat=k):
            valid = True
            m_in_comp = 0
            for x, y in edges:
                if x in comp and y in comp:
                    if assignment[x] == 1 and assignment[y] == 1:
                        valid = False
                        break
            if valid:
                count += 1
        return count

    def count_AB(comp):
        """|A ∩ B|: no sum 0 AND no sum 1"""
        # No sum 0: not(both 0)
        # No sum 1: (0,0) or (1,1)
        # Together: (1,1) only adjacent to (1,1) nodes
        # So all must be 1
        count = 1 if len(comp) > 0 else 1
        for x, y in edges:
            if x in comp and y in comp:
                if count == 0:
                    break
        return count

    def count_AC(comp):
        """|A ∩ C|: no sum 0 AND no sum 2"""
        # No sum 0: not(both 0)
        # No sum 2: not(both 1)
        # Together: adjacent must have different values (bipartite)
        from collections import deque
        # Check bipartite
        color = {}
        for x in comp:
            if x in color:
