                color = {}
                for x in comp:
                    color[x] = 0
                q = deque([seq[0]])
                while q:
                    u = q.popleft()
                    c = color[u]
                    for v in adj[u]:
                        if v in comp and v not in color:
                            color[v] = 1 - c
                            q.append(v)
                recheck = False
                for x, y in edges:
                    if x in comp and y in comp:
                        if color.get(x) == color.get(y):
