                if not recheck:
                    return 2
            return 2
        return 0 if len(comp) > 0 else 1

    def count_BC(comp):
        """|B ∩ C|: no sum 1 AND no sum 2"""
        # No sum 1: same value
        # No sum 2: not both 1
        # Together: all must be 0
        return 1

    def count_ABC(comp):
        """|A ∩ B ∩ C|: all three no-conditions hold"""
        # All must be 0: only 1 way
        return 1

    components = get_components()

    total = 2 ** n

    sum_A = 1
    sum_B = 1
    sum_C = 1
    sum_AB = 1
    sum_AC = 1
    sum_BC = 1
    sum_ABC = 1

    for comp in components:
        sum_A *= count_A(comp)
        sum_B *= count_B(comp)
        sum_C *= count_C(comp)
        sum_AB *= count_AB(comp)
        sum_AC *= count_AC(comp)
        sum_BC *= count_BC(comp)
        sum_ABC *= count_ABC(comp)

    union = sum_A + sum_B + sum_C - sum_AB - sum_AC - sum_BC + sum_ABC
    ans = total - union
