    def find_diameter():
        dist1 = bfs(1)
        farthest = max(range(1, n + 1), key=lambda x: dist1[x])
        dist2 = bfs(farthest)
        farthest2 = max(range(1, n + 1), key=lambda x: dist2[x])
        diameter = dist2[farthest2]
        return farthest, farthest2, dist2

    # LCA using binary lifting
    LOG = max(14, n.bit_length())
    parent = [[0] * (n + 1) for _ in range(LOG)]
    depth = [-1] * (n + 1)

    def dfs_lca(root, p, d):
        depth[root] = d
        parent[0][root] = p
        stack = [(root, p)]
        while stack:
            u, par = stack.pop()
            for v in adj[u]:
                if v != par and depth[v] == -1:
                    depth[v] = d + 1
                    parent[0][v] = u
                    stack.append((v, u))

    # Precompute binary lifting table
    def precompute_lca(start):
        dfs_lca(start, 0, 0)
        for j in range(1, LOG):
            for i in range(1, n + 1):
                if parent[j-1][i]:
                    parent[j][i] = parent[j-1][parent[j-1][i]]

    precompute_lca(1)

    def get_lca(u, v):
        if depth[u] < depth[v]:
            u, v = v, u

        # Bring u to same depth as v
        diff = depth[u] - depth[v]
        for j in range(LOG):
            if (diff >> j) & 1:
                u = parent[j][u]

        if u == v:
            return u

        for j in range(LOG - 1, -1, -1):
            if parent[j][u] != parent[j][v]:
                u = parent[j][u]
                v = parent[j][v]

        return parent[0][u]

    def dist_tree(u, v):
        return depth[u] + depth[v] - 2 * depth[get_lca(u, v)]

    # Strategy: add shortcuts to create a hub-and-spoke with diameter constraint
    # Use the center of the tree as a hub

    # Find tree center (minimize max distance to all nodes)
    def find_center():
        # Try each node, pick one that minimizes max distance
        best_center = 1
        best_max_dist = float('inf')
        dist1 = bfs(1)

        for node in range(1, n + 1):
            dist = bfs(node)
            max_d = max(dist)
            if max_d < best_max_dist:
                best_max_dist = max_d
                best_center = node

        return best_center, dist1

    center, _ = find_center()

    shortcuts = []

    # Add shortcuts from trees roots to reduce diameter
    # For each subtree, pick representative nodes to connect to center

    def get_subtree_size(u, p, visited):
        size = 1
        for v in adj[u]:
            if v != p and v not in visited:
                visited.add(v)
                size += get_subtree_size(v, u, visited)
        return size

    def get_subtree_nodes(u, p, visited, nodes):
        nodes.append(u)
        visited.add(u)
        for v in adj[u]:
            if v != p and v not in visited:
                get_subtree_nodes(v, u, visited, nodes)

    visited = {center}
    nodes = []
    get_subtree_nodes(center, -1, visited, nodes)

    # Add shortcuts to reduce distance
    for i in range(1, n + 1):
        if i != center and i not in nodes:
            # Connect this node to the center
            shortcuts.append((center, i))
            nodes.append(i)
            visited.add(i)

    # Ensure we don't add more than 10*n shortcuts
    if len(shortcuts) > 10 * n:
        shortcuts = shortcuts[:10 * n]

    # Format output
    if not shortcuts:
        return '0\n'

    result = str(len(shortcuts)) + '\n'
    for u, v in sorted(shortcuts):
        result += f'{u} {v}\n'

    return result.rstrip('\n') + '\n'

