import sys
from collections import deque

def solution(input_string):
    lines = input_string.strip().split('\n')
    if not lines:
        return ''

    n, m = map(int, lines[0].split())

    adj = [[] for _ in range(n + 1)]
    for i in range(1, m + 1):
        if i < len(lines):
            u, v = map(int, lines[i].split())
            adj[u].append(v)

    # BFS to compute shortest paths from each node
    def bfs(start):
        d = [float('inf')] * (n + 1)
        d[start] = 0
        queue = deque([start])
        while queue:
            u = queue.popleft()
            for v in adj[u]:
                if d[v] == float('inf'):
                    d[v] = d[u] + 1
                    queue.append(v)
        return d

    # Compute all-pairs shortest paths
    dist = [bfs(i) for i in range(1, n + 1)]

    # Precompute: for each k, list of (distance, l) sorted by distance descending
    # where l is any node l != k and dist[k][l] < inf
    best_l_for_k = [[] for _ in range(n + 1)]
    for k in range(1, n + 1):
        candidates = []
        for l in range(1, n + 1):
            if k != l and dist[k][l] != float('inf'):
                candidates.append((dist[k][l], l))
        if candidates:
            candidates.sort(reverse=True)
            best_l_for_k[k] = candidates

    max_dist = float('-inf')
    result = []

    # Iterate through all possible (i, j, k) combinations
    # For each, find best l != i, j
    for i in range(1, n + 1):
        for j in range(1, n + 1):
            if i == j or dist[i][j] == float('inf'):
                continue

            for k in range(1, n + 1):
                if k == i or k == j or dist[j][k] == float('inf'):
                    continue

                # Find best l for this (i, j, k)
                for dl, l in best_l_for_k[k]:
                    if l != i and l != j:
                        total = dist[i][j] + dist[j][k] + dl
                        if total > max_dist:
                            max_dist = total
                            result = [i, j, k, l]
                        break

    return ' '.join(map(str, result))


