    arr = list(map(int, lines[1].split()))

    # Handle edge case
    if n == 0:
        return "0"

    # Function to get prime factors
    def get_prime_factors(num):
        factors = set()
        d = 2
        temp = num
        while d * d <= temp:
            if temp % d == 0:
                factors.add(d)
                while temp % d == 0:
                    temp //= d
            d += 1
        if temp > 1:
            factors.add(temp)
        return factors

    # Get candidate primes from first and last elements
    primes = get_prime_factors(arr[0]) | get_prime_factors(arr[-1])

    INF = 10**18
    ans = INF

    for p in primes:
        # Calculate fix cost for each element
        change = [INF] * n
        for i in range(n):
            val = arr[i]
            if val % p == 0:
                change[i] = 0
            elif (val - 1) % p == 0 or (val + 1) % p == 0:
                change[i] = b
            else:
                change[i] = INF

        # Get all valid indices (where change[i] != INF)
        valid_indices = [i for i in range(n) if change[i] != INF]

        if not valid_indices:
            continue

        # Build prefix cost (cumulative from start)
        prefix = [INF] * n
        curr = 0
        for i in range(n):
            if change[i] != INF:
                curr += change[i]
                prefix[i] = curr

        # Build suffix cost (cumulative from end)
        suff = [INF] * n
        curr = 0
        for i in range(n - 1, -1, -1):
            if change[i] != INF:
                curr += change[i]
                suff[i] = curr

        # Try all valid configurations
        # Option 1: Keep only prefix up to i
        for i in range(n):
            if prefix[i] != INF:
                ans = min(ans, prefix[i])
                break

        # Option 2: Keep only suffix from j
        for j in range(n):
            if suff[j] != INF:
                ans = min(ans, suff[j])
                break

        # Option 3: Keep prefix (0 to i) and suffix (j to n-1), remove [i+1, j-1]
        for i in valid_indices:
            for j in valid_indices:
                if j <= i:
                    continue
                # Middle segment [i+1, j-1] removal cost
                gap = j - i - 1
                if gap < 0:
                    gap = 0

                if suff[j] != INF:
                    cost = prefix[i] + suff[j] + gap * a
                    ans = min(ans, cost)

    return str(max(0, ans))

