                            if p3_sub == p1_sub[::-1]:
                                total_len = p1_len + mid_len + len(p3_sub)

                                if best_total == 0 or total_len > best_total:
                                    best_total = total_len
                                    best_parts = (
                                        (p1_start + 1, p1_len),
                                        (p2_start + 1, mid_len),
                                        (p3_start + 1, len(p3_sub))
                                    )
                            break

    # Output format: k lines for number of parts, then parts
    if best_parts:
        result = [f"{len(best_parts)}"]
        result.extend(f"{s} {l}" for s, l in best_parts)
        return "\n".join(result) + "\n"
    else:
        # Fallback: output longest palindrome
        max_len = 0
        max_start = 1
        for center in range(n):
            for l, r in [(center, center), (center - 1, center)]:
                while l >= 0 and r < n and S[l] == S[r]:
                    if r - l + 1 > max_len:
                        max_len = r - l + 1
                        max_start = l + 1
                    l -= 1
                    r += 1
        return f"1\n{max_start} {max_len}\n"

