def solution(input_str):
    n, k, m = map(int, input_str.split())

    import functools

    @functools.lru_cache(maxsize=5000)
    def dp(current_pos, steps_remaining, visited):
        if steps_remaining == 0:
            return 1

        count = 0
        # Try next positions from 1 to current_pos + m
        end_pos = min(current_pos + m, n)
        for next_pos in range(1, end_pos + 1):
            if next_pos not in visited:
                count = (count + dp(next_pos, steps_remaining - 1, visited + (next_pos,))) % MOD
        return count

    total = 0
    for start in range(1, n + 1):
        total = (total + dp(start, k - 1, (start,))) % MOD

    return str(total)

