def solution(input_str):
    k, x, n, m = map(int, input_str.strip().split())

    # Track string growth limits - if too large, we know AC counting is impossible
    MAX_STRING = 2000000

    def generate_string(s1, s2, k, limit=MAX_STRING):
        """Generate sk, or return None if it would exceed limit"""
        # Using llist(limit) for Fibonacci-like growth tracking
        lens = [n, m]

        for i in range(3, k + 1):
            length = lens[i-2] + lens[i-1]
            if length > limit:
                return None
            lens.append(length)

        strings = [s1, s2]
        for i in range(3, k + 1):
            strings.append(strings[i-2] + strings[i-1])

        return strings[-1]

    def count_ac(s):
        return s.count('AC')

    def generate_patterns(length):
        """Generate all strings of given length made of A and C"""
        patterns = []
        for num_a in range(length + 1):
            patterns.append('A' * num_a + 'C' * (length - num_a))
        return patterns

    patterns1 = generate_patterns(n)
    patterns2 = generate_patterns(m)

    for s1 in patterns1:
        for s2 in patterns2:
            sk = generate_string(s1, s2, k)
            if sk is None:
                continue
            if count_ac(sk) == x:
                return f"{s1}\n{s2}\n"

    return "Happy new year!\n"

