def solution(input_str):
    # Parse input
    input_str = input_str.strip()
    lines = input_str.split('\n')

    first_line = lines[0].split()
    n, a, b = int(first_line[0]), int(first_line[1]), int(first_line[2])
    p = list(map(int, lines[1].split()))

    # Create lookup set for O(1) checking if a number is in input
    p_set = set(p)

    # Determine if each number can be in set A or B
    # can_A[i] is True if p[i] can be in set A (a - p[i] exists in input)
    # can_B[i] is True if p[i] can be in set B (b - p[i] exists in input)
    can_A = [False] * n
    can_B = [False] * n

    for i in range(n):
        x = p[i]
        if (a - x) in p_set:
            can_A[i] = True
        if (b - x) in p_set:
            can_B[i] = True

    # If any number cannot be in either set, it's impossible
    for i in range(n):
        if not can_A[i] and not can_B[i]:
            return "NO\n"

    # Union-Find to group numbers that must be in the same set
    parent = list(range(n))

    def find(x):
        if parent[x] != x:
            parent[x] = find(parent[x])
        return parent[x]

    def union(x, y):
        px, py = find(x), find(y)
        if px != py:
            parent[px] = py

    # Build edges: if a-x or b-x exists in input, those numbers must be in same set
    for i in range(n):
        x = p[i]
        if (a - x) in p_set:
            j = p.index(a - x)
            union(i, j)
        if (b - x) in p_set:
            j = p.index(b - x)
            union(i, j)

    # Group numbers into connected components
    components = {}
    for i in range(n):
        root = find(i)
        if root not in components:
            components[root] = []
        components[root].append(i)

    # Assign each component to set A (0) or B (1)
    assignment = [0] * n

    for component in components.values():
        all_can_A = all(can_A[i] for i in component)
        all_can_B = all(can_B[i] for i in component)

        if all_can_A:
            # Assign all to A
            for i in component:
                assignment[i] = 0
        elif all_can_B:
            # Assign all to B
            for i in component:
                assignment[i] = 1
        else:
            # Component cannot be validly assigned to A or B
            return "NO\n"

    # Format output with trailing space as per problem specification
    result = "YES\n"
    result += " ".join(map(str, assignment)) + " \n"
    return result

