                if v in color and color[v] == 1:
                    cycle_len = abs(tree_dist[u] + w - tree_dist[v])
                    g_val = gcd(g_val, cycle_len)
                elif v in color and color[v] == 0:
                    color[v] = 1
                    tree_dist[v] = tree_dist[u] + w
                    dfs_stack.append(v)
                    edges_done = True
                    break

            if not dfs_stack:
                color[u] = 2
                dfs_stack.pop()

        for node in scc:
