def solution(input_str):
    N = int(input_str.strip())

    def digital_root(n):
        if n == 0:
            return 0
        return (n - 1) % 9 + 1

    # Count how many numbers in [1, N] have each digital root
    count_by_dr = [0] * 10
    for i in range(1, N + 1):
        dr = digital_root(i)
        count_by_dr[dr] += 1

    # Count all triples where d(AB) = d(C)
    # The digital root of product: d(AB) = d(d(A)*d(B))
    total = 0
    for da in range(1, 10):
        for db in range(1, 10):
            prod_dr = digital_root(da * db)
            total += count_by_dr[da] * count_by_dr[db] * count_by_dr[prod_dr]

    # Subtract triples where AB = C exactly
    for C in range(1, N + 1):
        for A in range(1, int(C**0.5) + 2):
            if C % A == 0:
                B = C // A
                if B >= 1:
                    total -= 1

    return str(total)

