    for i in range(1, n + 1):
        pos, a = map(int, lines[i].split())
        frogs[i] = {'id': i, 'pos': pos, 'a': a, 'alive': True}

    alive_indices = list(range(1, n + 1))

    # Each complete round: process all turns once
    while True:
        made_any = False
        next_alive = []

        for ptr in range(len(alive_indices)):
            f_idx = alive_indices[ptr]
            f = frogs[f_idx]

            if not f['alive'] or f['a'] <= 0:
                continue

            start = f['pos']
            dest = (start + f['a'] - 1) % m + 1

            # Count frogs knocked out on the path
            knocked_count = 0

            for other_idx in alive_indices:
                if other_idx == f_idx:
                    continue
                other = frogs[other_idx]
                if not other['alive']:
                    continue

                if start == dest:
                    continue

                if start < dest:
                    if start < other['pos'] <= dest:
                        knocked_count += 1
                else:  # start > dest (wrapping around)
                    if other['pos'] > start or other['pos'] <= dest:
                        knocked_count += 1

            # Update frog's jump value
            if f_idx != 0:
                new_jump = f['a'] - knocked_count
                f['a'] = new_jump
                made_any = True

                if new_jump <= 0:
                    f['alive'] = False

            next_alive.append(f_idx)

        alive_indices = next_alive

        if not made_any and not any(frogs[i]['a'] > 0 for i in range(1, n + 1)):
            break

    # Also check for any frogs that should be removed
    alive_indices = [i for i in alive_indices if frogs[i]['alive']]

    result = sorted([frogs[i]['id'] for i in alive_indices])

    output = str(len(result)) + '\n'
    if result:
        output += ' '.join(map(str, result)) + '\n'

    return output


