import sys
from functools import lru_cache

def solution(input_str):
    # Parse input
    lines = input_str.strip().split('\n')
    if not lines:
        return ""

    t = int(lines[0])
    queries = [int(x) for x in lines[1:t+1]]

    # Generate Fibonacci numbers F1=1, F2=2, ..., up to 10^18
    fib = [1, 2]
    while fib[-1] < 10**18:
        fib.append(fib[-1] + fib[-2])

    # Memoized function to count ways to decompose 'rem' using fib[idx:]
    @lru_cache(maxsize=None)
    def count_ways(idx, rem):
        if rem == 0:
            return 1
        if idx >= len(fib) or fib[idx] > rem:
            return 0

        # Option 1: Don't use fib[idx], move to next Fibonacci
        ans = count_ways(idx + 1, rem)

        # Option 2: Use fib[idx], move to next Fibonacci (distinct numbers)
        if rem >= fib[idx]:
            ans += count_ways(idx + 1, rem - fib[idx])

        return ans

    # Answer each query
    results = []
    for n in queries:
        ans = count_ways(0, n)
        results.append(str(ans))

    return '\n'.join(results)

